#!/bin/bash
# Task 073 -- meshsim v1.2 (WORKER4, branch v1.2-meshsim at 13a3053): phase 4's full-mode runs (CtrlTest full,
# AccountingTest full, the quick parameter sweep, ReadPortGatherTest full, EngineTest full), in parallel. The kit
# (attempt 2: hops.txt and data/ added) (meshsim's compiled classes, Java 17 bytecode, the tile images, the boot ROM, run_full.sh) is embedded below as a base64 tgz, SHA-256
# checked; no other input. Commits VERDICT.txt, rc.txt, every log and the CSVs. Expected 15-30 min.
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/073-meshsim-v12-phase4-full; mkdir -p "$RES"
WANT=c4205bbc4daa05cbda7ca3db0bc98b57995c547d4b03beaa0031e6197560bf4f
W=/tmp/ms-073; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
cd "$W/meshsim" || exit 2
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
./run_full.sh "$W/out"; RC=$?
echo "run_full.sh exit $RC at $(date -u)"
cp "$W"/out/* "$RES/" 2>/dev/null
cat "$W/out/VERDICT.txt" 2>/dev/null
exit $RC
